-- AI Value Readiness
-- Select an approved installation role, a writable destination database, and a warehouse.
-- Run the complete file unchanged. Open OPEN_APP_URL in the final result.
-- Start with Small compute; Medium is optional for heavier work, not required for AI.
-- The selected database is the installation destination, not an account-wide access grant.
-- Discovery searches up to 20 role-visible databases; coverage reports skipped scopes.
-- AI needs the required USE AI FUNCTION privileges, a Cortex database role, and model access.
-- Warehouse work, AI calls and source packaging can incur charges. Existing approval gates remain.
-- No automatic privilege grants. Production actions and schedules require separate approval.
-- Optional settings are below; no edits are required. Full settings remain in readable source.
-- Readable implementation: EDIT_SOURCE_URL when available, or this solution's repository source.
-- Remove with this solution's TEARDOWN operation, not by dropping an unrelated schema.
EXECUTE IMMEDIATE $$
DECLARE
CONFIG_TEXT VARCHAR DEFAULT
-- BEGIN EDITABLE CONFIG
'{
  "action": "INSTALL",
  "approve": true,
  "database": "",
  "schema": "",
  "warehouse": "",
  "scope": [],
  "allow_ai_metadata": true
}'
-- END EDITABLE CONFIG
;
RUNNER VARCHAR DEFAULT DECOMPRESS_STRING(TO_BINARY('', 'BASE64'), 'ZLIB');
RESULT VARIANT;
BEGIN
EXECUTE IMMEDIATE :RUNNER USING(CONFIG_TEXT);
SELECT $1 INTO :RESULT FROM TABLE(RESULT_SCAN(LAST_QUERY_ID()));

  LET launch_config VARIANT := PARSE_JSON(:CONFIG_TEXT);
  IF (:RESULT:schema IS NOT NULL AND COALESCE(:launch_config:database::VARCHAR,'')='') THEN
    launch_config := OBJECT_INSERT(:launch_config,'database',CURRENT_DATABASE(),TRUE);
  END IF;
  IF (:RESULT:schema IS NOT NULL AND COALESCE(:launch_config:schema::VARCHAR,'')='') THEN
    launch_config := OBJECT_INSERT(:launch_config,'schema','AI_VALUE_READINESS',TRUE);
  END IF;
  LET launch_target ARRAY := COALESCE(:launch_config:target::ARRAY, ARRAY_CONSTRUCT(:launch_config:database::VARCHAR, :launch_config:schema::VARCHAR));
  IF (:RESULT:app IS NOT NULL AND (ARRAY_SIZE(:launch_target)<>2 OR COALESCE(:launch_target[0]::VARCHAR,'')='' OR COALESCE(:launch_target[1]::VARCHAR,'')='')) THEN
    LET returned_app VARCHAR := REPLACE(:RESULT:app::VARCHAR,'"','');
    IF (REGEXP_LIKE(:returned_app,'[A-Za-z_][A-Za-z0-9_$]*[.][A-Za-z_][A-Za-z0-9_$]*[.][A-Za-z_][A-Za-z0-9_$]*')) THEN
      launch_target := ARRAY_CONSTRUCT(SPLIT_PART(:returned_app,'.',1),SPLIT_PART(:returned_app,'.',2));
    END IF;
  END IF;
  LET launch_status VARCHAR := COALESCE(:RESULT:status::VARCHAR, :RESULT:state::VARCHAR, 'UNKNOWN');
  LET launch_url VARCHAR := NULL;
  IF (:launch_config:approve::BOOLEAN = TRUE AND ARRAY_SIZE(:launch_target) = 2
      AND ((:launch_status = 'COMPLETE' AND :RESULT:phase::VARCHAR = 'INSTALL') OR :launch_status = 'INSTALLED')) THEN
    BEGIN
      LET launch_schema VARCHAR := '"' || REPLACE(:launch_target[0]::VARCHAR, '"', '""') || '"."' || REPLACE(:launch_target[1]::VARCHAR, '"', '""') || '"';
      EXECUTE IMMEDIATE 'SHOW STREAMLITS IN SCHEMA ' || :launch_schema;
      LET launch_exists BOOLEAN := (SELECT COUNT(*) = 1 FROM TABLE(RESULT_SCAN(LAST_QUERY_ID())) WHERE "name" = 'AI_VALUE_READINESS');
      IF (:launch_exists) THEN
        launch_url := 'https://app.snowflake.com/' || LOWER(CURRENT_ORGANIZATION_NAME()) || '/' || LOWER(CURRENT_ACCOUNT_NAME()) || '/#/streamlit-apps/' || :launch_target[0]::VARCHAR || '.' || :launch_target[1]::VARCHAR || '.AI_VALUE_READINESS';
        IF (:RESULT:state::VARCHAR IN ('METADATA_REVIEW_APP','EXISTING_APP_PRESERVED')) THEN
          launch_status := 'APP_READY_REVIEW_REQUIRED';
        END IF;
      ELSE
        launch_status := 'APP_NOT_FOUND';
      END IF;
    EXCEPTION WHEN OTHER THEN
      launch_status := 'APP_VERIFICATION_FAILED';
    END;
  END IF;
  LET launch_receipt RESULTSET := (SELECT :launch_status AS STATUS, :launch_url AS OPEN_APP_URL, :RESULT:edit_source_url::VARCHAR AS EDIT_SOURCE_URL, COALESCE(:RESULT:source_status::VARCHAR,'NOT_VERIFIED') AS SOURCE_STATUS, :RESULT:source_error::VARCHAR AS SOURCE_ERROR, IFF(:launch_url IS NOT NULL,'OPEN THE APP: click OPEN_APP_URL. No additional variable changes are needed.','No app link is available. Inspect RESULT for the exact prerequisite or failure.') AS NEXT_ACTION, :RESULT AS RESULT);
  RETURN TABLE(launch_receipt);
END;
$$;
